'use strict'

import { CAVE_MONEY_GAME, CAVE_PAY_TO_TALK, CAVE_POTION_SHOP } from '../constant'

// What each kind of cave does (see CAVES in constant.js and docs/rom-analysis.md, Cavernes)

// The money making game: one rupee wins, the other two lose. Measured over 60 games in the ROM:
// +20 with -10 and -40, or +50 with -10 and -10, in any order
const MONEY_GAME_DRAWS = [[20, -10, -40], [50, -10, -10]]

// The three values hidden under the rupees, left to right
export function drawMoneyGame (random = Math.random) {
  const values = [...MONEY_GAME_DRAWS[Math.floor(random() * MONEY_GAME_DRAWS.length)]]
  for (let i = values.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1))
    ;[values[i], values[j]] = [values[j], values[i]]
  }
  return values
}

export function formatSigned (value) {
  return value > 0 ? `+${value}` : `${value}`
}

// What is written under an item: its price, or what it costs to play or to talk
export function getPriceLabel (cave, price) {
  if (!price) {
    return undefined
  }
  return cave === CAVE_MONEY_GAME || cave === CAVE_PAY_TO_TALK ? `-${price}` : `${price}`
}

// The potion shop shows nothing until Link has shown the letter there
export function isCaveClosed (map, link) {
  return map.cave === CAVE_POTION_SHOP && !link.inventory.letterShown
}
