'use strict'

import clock from '../../service/clock'
import { SPRITE_SCALE } from '../../constant'

// TODO remove this and handle draw directly in Sprite class
// An image of the atlas, at the NES resolution (width and height in NES pixels), drawn SPRITE_SCALE
// times bigger and without smoothing (sharp pixels)
class SpriteImage {
  constructor (name, file, offset, width, height) {
    this.name = name
    this.file = file
    this.offset = offset
    this.width = width
    this.height = height
  }

  // x, y, w, h: part of the image to draw, in screen pixels as the destination
  draw (context, x, y, w, h, dx, dy, dw, dh) {
    context.imageSmoothingEnabled = false
    if (dx !== undefined && dy !== undefined && dw !== undefined && dh !== undefined) {
      context.drawImage(this.file, this.offset.x + x / SPRITE_SCALE, this.offset.y + y / SPRITE_SCALE, w / SPRITE_SCALE, h / SPRITE_SCALE, dx, dy, dw, dh)
      return
    }

    context.drawImage(this.file, this.offset.x, this.offset.y, this.width, this.height, x, y, w, h)
  }
}

class Sprite {
  constructor (name, type, images) {
    this.name = name
    this.type = type
    this.images = images

    this.currentImageIndex = 0
    this.incrementSpeed = 200
    this.incrementTimer = undefined
  }

  clone () {
    return new Sprite(this.name, this.type, this.images)
  }

  start () {
    // A timer cancelled from outside (clock reset for a new game) no longer animates: start again
    if (this.incrementTimer && !this.incrementTimer.cancelled) {
      return
    }

    this.incrementImageIndex()
    this.incrementTimer = clock.repeat(() => this.incrementImageIndex(), this.incrementSpeed)

    return this
  }

  stop () {
    this.incrementTimer?.cancel()
    this.incrementTimer = undefined

    return this
  }

  incrementImageIndex () {
    if (!this.images) {
      return
    }

    this.currentImageIndex++
    if (this.currentImageIndex >= this.images.length) {
      this.currentImageIndex = 0
    }
  }

  draw (context, x, y, w, h, x2, y2, w2, h2) {
    if (!this.images || !this.images[this.currentImageIndex]) {
      return
    }

    this.images[this.currentImageIndex].draw(context, x, y, w, h, x2, y2, w2, h2)
  }

  // In screen pixels
  get width () {
    return this.images[this.currentImageIndex]?.width * SPRITE_SCALE
  }

  get height () {
    return this.images[this.currentImageIndex]?.height * SPRITE_SCALE
  }
}

export { Sprite, SpriteImage }
