'use strict'

import resource from '../../resource'
import { TILE_WIDTH, ENEMY_OCTOROK_RED, ENEMY_OCTOROK_RED_FAST, ENEMY_OCTOROK_BLUE, ENEMY_OCTOROK_BLUE_FAST, ENEMY_MOBLIN_RED, ENEMY_MOBLIN_BLUE, ENEMY_LYNEL_RED, ENEMY_LYNEL_BLUE } from '../../constant'
import { Enemy, DIRECTION_VECTORS, DIRECTIONS, STATE_SPAWNING, STATE_WAITING, STATE_HURT, randomInt, pick, isFree, isInside, drawImage } from './common'
import { Rock, Arrow, Sword } from './projectile'

// Enemies that walk on the grid and shoot straight ahead: octoroks (rocks), moblins (arrows),
// lynels (swords). Life in hits of the wooden sword, speed in pixels per step, damage in hearts
export const WALKERS = {
  [ENEMY_OCTOROK_RED]: { sprite: 'octorok_red', life: 1, speed: 1, contactDamage: 0.5, shot: 'rock' },
  [ENEMY_OCTOROK_RED_FAST]: { sprite: 'octorok_red', life: 1, speed: 2, contactDamage: 0.5, shot: 'rock' },
  [ENEMY_OCTOROK_BLUE]: { sprite: 'octorok_blue', life: 2, speed: 1, contactDamage: 0.5, shot: 'rock' },
  [ENEMY_OCTOROK_BLUE_FAST]: { sprite: 'octorok_blue', life: 2, speed: 2, contactDamage: 0.5, shot: 'rock' },
  [ENEMY_MOBLIN_RED]: { sprite: 'moblin_red', life: 2, speed: 1, contactDamage: 0.5, shot: 'arrow' },
  [ENEMY_MOBLIN_BLUE]: { sprite: 'moblin_blue', life: 3, speed: 1, contactDamage: 1, shot: 'arrow' },
  [ENEMY_LYNEL_RED]: { sprite: 'lynel_red', life: 4, speed: 1, contactDamage: 1, shot: 'sword', color: 'red', shotDamage: 1 },
  [ENEMY_LYNEL_BLUE]: { sprite: 'lynel_blue', life: 6, speed: 1, contactDamage: 2, shot: 'sword', color: 'blue', shotDamage: 2 }
}

// Walkers walk on a grid of half tiles and only turn or stop on it
const GRID = TILE_WIDTH / 2
// Half tiles walked before turning, at random
const MIN_CELLS = 1
const MAX_CELLS = 6
// Chance, on each point of the grid, to stop and shoot
const THROW_CHANCE = 1 / 8
const AIM_STEPS = 30
const AFTER_THROW_STEPS = 15
const WALK_FRAME_PIXELS = 8

const STATE_ENTERING = 'entering'
const STATE_WALKING = 'walking'
const STATE_AIMING = 'aiming'

class Walker extends Enemy {
  constructor (type, x, y, direction, random = Math.random) {
    const config = WALKERS[type]
    super(type, x, y, config, random)
    this.config = config
    this.color = config.sprite.split('_')[1]
    this.speed = config.speed
    this.direction = direction

    this.state = STATE_WALKING
    this.delay = 0 // Before walking in, for the enemies arriving from the edges
    this.cellsLeft = 0
    this.walkedPixels = 0
    this.decidedAt = undefined
    this.rock = undefined // The last shot, still flying
  }

  static inCloud (type, x, y, random = Math.random) {
    const walker = new this(type, x, y, pick(random, DIRECTIONS), random)
    walker.setState(STATE_SPAWNING)
    return walker
  }

  static fromEdge (type, x, y, direction, delay, random = Math.random) {
    const walker = new this(type, x, y, direction, random)
    walker.setState(STATE_WAITING)
    walker.delay = delay
    return walker
  }

  isOnGrid (map) {
    return (this.x - map.x) % GRID === 0 && (this.y - map.y) % GRID === 0
  }

  // Free over distance pixels: on the grid, the whole next half tile must be (so it only stops on the grid)
  canMove (map, direction, distance = 1) {
    const [dx, dy] = DIRECTION_VECTORS[direction]
    return isFree(map, this.x + dx * distance, this.y + dy * distance)
  }

  // A new direction at random among the free ones (staying still when walled in)
  turn (map, distance = 1) {
    const free = DIRECTIONS.filter(direction => this.canMove(map, direction, distance))
    if (free.length > 0) {
      this.direction = pick(this.random, free)
    }
    this.cellsLeft = randomInt(this.random, MIN_CELLS, MAX_CELLS)
  }

  start (map) {
    this.setState(STATE_WALKING)
    this.turn(map)
  }

  // On a point of the grid: maybe shoot, maybe turn. True when the walker stops to shoot
  decide (map) {
    // Once per point (it is still there after shooting)
    const position = `${this.x},${this.y}`
    if (this.decidedAt !== position) {
      this.decidedAt = position
      if (!this.rock && this.random() < THROW_CHANCE) {
        this.setState(STATE_AIMING)
        return true
      }
      this.cellsLeft--
      if (this.cellsLeft <= 0) {
        this.turn(map, GRID)
      }
    }
    if (!this.canMove(map, this.direction, GRID)) {
      this.turn(map, GRID)
    }
    return false
  }

  walk (map) {
    for (let i = 0; i < this.speed; i++) {
      if (this.isOnGrid(map) && this.decide(map)) {
        return
      }
      // A wall ahead off the grid (after being pushed back, or along a diagonal wall): another way
      if (!this.canMove(map, this.direction)) {
        this.turn(map)
        if (!this.canMove(map, this.direction)) {
          return
        }
      }
      const [dx, dy] = DIRECTION_VECTORS[this.direction]
      this.x += dx
      this.y += dy
      this.walkedPixels++
    }
  }

  // From outside the screen, straight in, over everything
  enter (map) {
    const [dx, dy] = DIRECTION_VECTORS[this.direction]
    this.x += dx * this.speed
    this.y += dy * this.speed
    this.walkedPixels += this.speed
    // Once on the screen, it goes on inwards for a while
    if (isInside(map, this.x, this.y, this.width, this.height)) {
      this.setState(STATE_WALKING)
      this.cellsLeft = randomInt(this.random, MIN_CELLS, MAX_CELLS)
    }
  }

  // Walks again after being pushed back, even when hit while aiming
  hit (link, weapon) {
    super.hit(link, weapon)
    if (this.state === STATE_HURT) {
      this.resumeState = STATE_WALKING
    }
  }

  shoot (map) {
    const { shot, color, shotDamage } = this.config
    const projectile = shot === 'arrow'
      ? new Arrow(this.x, this.y, this.direction)
      : shot === 'sword' ? new Sword(this.x, this.y, this.direction, color, shotDamage) : new Rock(this.x, this.y, this.direction)
    map.projectiles.push(projectile)
    this.rock = projectile
  }

  act (map) {
    if (this.rock?.done) {
      this.rock = undefined
    }
    switch (this.state) {
      case STATE_WAITING:
        if (this.steps >= this.delay) {
          this.setState(STATE_ENTERING)
        }
        break
      case STATE_ENTERING:
        this.enter(map)
        break
      case STATE_WALKING:
        this.walk(map)
        break
      case STATE_AIMING:
        if (this.steps === AIM_STEPS) {
          this.shoot(map)
        }
        if (this.steps >= AIM_STEPS + AFTER_THROW_STEPS) {
          this.setState(STATE_WALKING)
        }
        break
    }
  }

  drawBody (context) {
    const frame = Math.floor(this.walkedPixels / WALK_FRAME_PIXELS) % 2
    drawImage(context, resource.getSprite(`${this.config.sprite}_${this.direction}_move`), frame, this.x, this.y, this.width, this.height)
  }
}

// The first walker of the game (the tests and the editor still call it that)
const Octorok = Walker

export { Walker, Octorok }
